} from "@/components/domain/board/board-model";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

const ORG_ID = "org_1" as OrgId;
const PROJECT_ID = "prj_1" as ProjectId;
const AUTHOR_ID = "usr_1" as UserId;

function issue(
  id: string,
  status: IssueStatus,
  priority: IssuePriority = "none",
  createdAt = "2026-01-01T00:00:00.000Z",
): Issue {
  return {
    id: id as IssueId,
    orgId: ORG_ID,
    projectId: PROJECT_ID,
    number: Number(id.replace(/\D/g, "")) || 1,
    title: `Issue ${id}`,
    description: null,
    status,
    priority,
    authorId: AUTHOR_ID,
    assigneeId: null,
    parentId: null,
    estimate: null,
    dueAt: null,
    startedAt: null,
    completedAt: null,
    labelIds: [],
    archivedAt: null,
    createdAt: toIsoTimestamp(createdAt),
    updatedAt: toIsoTimestamp(createdAt),
  };
}

describe("board-model/buildBoardColumns", () => {
  it("creates one column per status in workflow order", () => {
    const columns = buildBoardColumns([issue("i1", "todo")]);
    expect(columns.map((column) => column.status)).toEqual([
      "backlog",
      "todo",
      "in_progress",
      "in_review",
      "done",
      "canceled",
    ]);
  });

  it("counts each column and keeps empty ones", () => {
    const columns = buildBoardColumns([
      issue("i1", "todo"),
      issue("i2", "todo"),
      issue("i3", "done"),
    ]);
    const byStatus = new Map(columns.map((c) => [c.status, c]));
    expect(byStatus.get("todo")?.total).toBe(2);
    expect(byStatus.get("done")?.total).toBe(1);
    expect(byStatus.get("backlog")?.issues).toEqual([]);
  });

  it("orders a column by priority first, then age", () => {
    const columns = buildBoardColumns([
      issue("i1", "todo", "low", "2026-01-01T00:00:00.000Z"),
      issue("i2", "todo", "urgent", "2026-02-01T00:00:00.000Z"),
      issue("i3", "todo", "low", "2025-12-01T00:00:00.000Z"),
    ]);
    const todo = columns.find((column) => column.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i2", "i3", "i1"]);
  });
});

describe("board-model/compareBoardIssues", () => {
  it("ranks urgent above high", () => {
    expect(
      compareBoardIssues(issue("a", "todo", "urgent"), issue("b", "todo", "high")),
    ).toBeLessThan(0);
  });
});

describe("board-model/moveIssueInColumns", () => {
  const columns = buildBoardColumns([
    issue("i1", "todo"),
    issue("i2", "todo"),
    issue("i3", "in_progress"),
  ]);

  it("moves an issue between columns and rewrites its status", () => {
    const next = moveIssueInColumns(columns, "i1" as IssueId, "in_progress", 0);
    const todo = next.find((c) => c.status === "todo");
    const inProgress = next.find((c) => c.status === "in_progress");

    expect(todo?.issues.map((i) => i.id)).toEqual(["i2"]);
    expect(todo?.total).toBe(1);
    expect(inProgress?.issues.map((i) => i.id)).toEqual(["i1", "i3"]);
    expect(findIssue(next, "i1" as IssueId)?.status).toBe("in_progress");
  });

  it("clamps an index past the end of the target column", () => {
    const next = moveIssueInColumns(columns, "i3" as IssueId, "todo", 99);
    const todo = next.find((c) => c.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i1", "i2", "i3"]);
  });

  it("re-orders within the same column without duplicating the card", () => {
    const next = moveIssueInColumns(columns, "i2" as IssueId, "todo", 0);
    const todo = next.find((c) => c.status === "todo");
    expect(todo?.issues.map((i) => i.id)).toEqual(["i2", "i1"]);
    expect(todo?.total).toBe(2);
  });

  it("leaves the board untouched for an unknown issue", () => {
    expect(moveIssueInColumns(columns, "nope" as IssueId, "done", 0)).toBe(
      columns,
    );
  });
});

describe("board-model/orderColumns", () => {
  it("restores workflow order from an arbitrary arrangement", () => {
    const scrambled = [
      { status: "done" as IssueStatus, issues: [], total: 0 },
      { status: "backlog" as IssueStatus, issues: [], total: 0 },
    ];
    expect(orderColumns(scrambled).map((c) => c.status)).toEqual([
      "backlog",
      "done",
    ]);
  });
});
"use client";

/**
 * Create/edit form bound to `createIssueSchema` through `zodResolver`.
 *
 * The schema is the same object the Server Action re-parses, so a field the
 * client accepts can never be one the server rejects — that shared definition
 * is the whole point of keeping the Zod schemas outside both layers.
 *
 * Must call (do not reimplement): createIssueSchema
 */
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm, useWatch } from "react-hook-form";
import { Button } from "@/components/ui/button";
import { ErrorMessage } from "@/components/ui/error-message";
import { FormField } from "@/components/ui/form-field";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useFormAction } from "@/hooks/use-form-action";
import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
import type { ActionResult } from "@/types/api";
import type { IsoTimestamp, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue, IssueLabel } from "@/types/issue";
import type { MemberWithUser } from "@/types/member";
import type { ReactElement } from "react";
import { IssueAssigneePicker } from "./issue-assignee-picker";
import { IssueDueDateField } from "./issue-due-date-field";
import { IssueLabelPicker } from "./issue-label-picker";
import { IssuePrioritySelect } from "./issue-priority-select";
import { IssueStatusSelect } from "./issue-status-select";

export type IssueFormProps = {
  orgId: OrgId;
  projectId: ProjectId;
  defaultValues?: Partial<CreateIssueInput>;
  members: readonly MemberWithUser[];
  labels: readonly IssueLabel[];
  onSubmit: (input: CreateIssueInput) => Promise<ActionResult<Issue>>;
};

export function IssueForm(props: IssueFormProps): ReactElement | null {
  const { orgId, projectId, defaultValues, members, labels, onSubmit } = props;

  const form = useForm({
    resolver: zodResolver(createIssueSchema),
    defaultValues: {
      orgId,
      projectId,
      title: "",
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
      ...defaultValues,
    },
  });

  const { submit, pending, error } = useFormAction(onSubmit, {
    onSuccess: () => form.reset(),
  });

  const values = useWatch({ control: form.control });
  const fieldError = (name: keyof CreateIssueInput): string | null =>
    form.formState.errors[name]?.message ?? null;

  return (
    <form
      className="space-y-4"
      onSubmit={form.handleSubmit((input) => submit(input))}
    >
      <FormField
        name="title"
        label="Title"
        required
        error={fieldError("title")}
      >
        <Input
          name="title"
          value={values.title ?? ""}
          placeholder="Something is broken"
          invalid={fieldError("title") !== null}
          onChange={(value) => form.setValue("title", value)}
        />
      </FormField>

      <FormField name="description" label="Description">
        <Textarea
          name="description"
          rows={6}
          value={values.description ?? ""}
          placeholder="What happened, and what did you expect?"
          onChange={(value) =>
            form.setValue("description", value.length === 0 ? null : value)
          }
        />
      </FormField>

      <div className="grid gap-4 sm:grid-cols-2">
        <FormField name="status" label="Status">
          <IssueStatusSelect
            value={values.status ?? "backlog"}
            onChange={(status) => form.setValue("status", status)}
          />
        </FormField>

        <FormField name="priority" label="Priority">
          <IssuePrioritySelect
            value={values.priority ?? "none"}
            onChange={(priority) => form.setValue("priority", priority)}
          />
        </FormField>

        <FormField name="assigneeId" label="Assignee">
          <IssueAssigneePicker
            value={(values.assigneeId ?? null) as UserId | null}
            members={members}
            onChange={(userId) => form.setValue("assigneeId", userId)}
          />
        </FormField>

        <FormField name="dueAt" label="Due date">
          <IssueDueDateField
            value={(values.dueAt ?? null) as IsoTimestamp | null}
            onChange={(dueAt) => form.setValue("dueAt", dueAt)}
          />
        </FormField>
      </div>

      <FormField name="labelIds" label="Labels">
        <IssueLabelPicker
          value={(values.labelIds ?? []) as unknown as readonly LabelId[]}
          labels={labels}
          onChange={(labelIds) => form.setValue("labelIds", [...labelIds])}
        />
      </FormField>

      <ErrorMessage message={error?.message ?? null} />

      <Button type="submit" loading={pending} disabled={pending}>
        Create issue
      </Button>
    </form>
  );
}

import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

