import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, projectResource, requireFound } from "./_support";
import type { CloseMilestoneInput, CreateMilestoneInput, UpdateMilestoneInput } from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";

async function authorizeProject(actor: Actor, orgId: OrgId, projectId: ProjectId, write: boolean): Promise<void> {
  const project = requireFound(await projectRepo.findProjectById(orgId, projectId), "Project", projectId);
  assertCan(actor, write ? "project:update" : "project:read", projectResource(project));
  if (write) assertNotArchived("Project", project.id, project);
}

function loadMilestone(orgId: OrgId, milestoneId: MilestoneId): Milestone {
  return requireFound(milestoneRepo.findMilestoneById(orgId, milestoneId), "Milestone", milestoneId);
}

export async function createMilestone(actor: Actor, input: CreateMilestoneInput): Promise<Milestone> {
  const now = toIsoTimestamp(new Date());
  assertOrgScope(actor, input.orgId);
  await authorizeProject(actor, input.orgId, input.projectId, true);
  const milestone = milestoneRepo.insertMilestone(input, now);
  await emit("milestone.created", {
    ...actorEnvelope(actor), occurredAt: now,
    milestoneId: milestone.id, projectId: milestone.projectId,
  });
  return milestone;
}

export async function updateMilestone(actor: Actor, input: UpdateMilestoneInput): Promise<Milestone> {
  const now = toIsoTimestamp(new Date());
  assertOrgScope(actor, input.orgId);
  const milestone = loadMilestone(input.orgId, input.milestoneId);
  await authorizeProject(actor, input.orgId, milestone.projectId, true);
  return milestoneRepo.updateMilestone(input, now);
}

export async function closeMilestone(actor: Actor, input: CloseMilestoneInput): Promise<{
  milestone: Milestone;
  movedIssueIds: readonly IssueId[];
}> {
  const now = toIsoTimestamp(new Date());
  assertOrgScope(actor, input.orgId);
  const milestone = loadMilestone(input.orgId, input.milestoneId);
  await authorizeProject(actor, input.orgId, milestone.projectId, true);
  const result = milestoneRepo.closeMilestone(input, now);
  await emit("milestone.closed", {
    ...actorEnvelope(actor), occurredAt: now,
    milestoneId: milestone.id, projectId: milestone.projectId,
    movedToMilestoneId: input.moveOpenIssuesTo,
    movedIssueIds: result.movedIssueIds,
  });
  return result;
}

export async function reopenMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<Milestone> {
  const now = toIsoTimestamp(new Date());
  assertOrgScope(actor, orgId);
  const before = loadMilestone(orgId, milestoneId);
  await authorizeProject(actor, orgId, before.projectId, true);
  const milestone = milestoneRepo.reopenMilestone(orgId, milestoneId, now);
  await emit("milestone.reopened", {
    ...actorEnvelope(actor), occurredAt: now,
    milestoneId: milestone.id, projectId: milestone.projectId,
  });
  return milestone;
}

function withProgress(milestone: Milestone, now: number): MilestoneWithProgress {
  const progress = milestoneRepo.getMilestoneProgress(milestone.orgId, milestone.id);
  return {
    milestone,
    progress,
    overdue: milestone.closedAt === null && milestone.targetDate !== null
      && new Date(milestone.targetDate).getTime() < now && progress.open > 0,
  };
}

export async function listMilestones(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<readonly MilestoneWithProgress[]> {
  const now = Date.now();
  assertOrgScope(actor, orgId);
  await authorizeProject(actor, orgId, projectId, false);
  return milestoneRepo.listMilestones(orgId, projectId).map((milestone) => withProgress(milestone, now));
}

export async function getMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<MilestoneWithProgress> {
  const now = Date.now();
  assertOrgScope(actor, orgId);
  const milestone = loadMilestone(orgId, milestoneId);
  await authorizeProject(actor, orgId, milestone.projectId, false);
  return withProgress(milestone, now);
}
